// ============================================================
// WhaleTrace API — 回傳全部股票籌碼快照
// GET /whaletrace-snapshot?ticker=AAPL  → 單檔
// GET /whaletrace-snapshot               → 全部
// ============================================================

// 從 workflow staticData 讀取最新爬蟲資料
const staticData = $getWorkflowStaticData('global');
let snapshots = [];
try {
  if (staticData.snapshots) {
    snapshots = JSON.parse(staticData.snapshots);
  }
} catch (e) {}

// 支援 query param: ?ticker=AAPL
const query = $input.first().json.query || {};
const ticker = query.ticker;

let result;
if (ticker) {
  result = snapshots.filter(s => s.ticker.toUpperCase() === ticker.toUpperCase());
  if (result.length === 0) {
    result = { error: `Ticker ${ticker} not found`, available: snapshots.map(s => s.ticker) };
  } else {
    result = result[0];
  }
} else {
  result = {
    data: snapshots,
    total: snapshots.length,
    generated_at: staticData.generated_at || new Date().toISOString()
  };
}

return [{ json: result }];

// ============================================================
// WhaleTrace API — 機構持股明細
// GET /whaletrace-institutional?ticker=NVDA&page=1&page_size=20
// ============================================================

const staticData = $getWorkflowStaticData('global');
let holdings = [];
try {
  if (staticData.holdings) {
    holdings = JSON.parse(staticData.holdings);
  }
} catch (e) {}

const query = $input.first().json.query || {};
const ticker = query.ticker;
const page = parseInt(query.page) || 1;
const pageSize = parseInt(query.page_size) || 20;

let result;
if (ticker) {
  let filtered = holdings.filter(h => h.ticker.toUpperCase() === ticker.toUpperCase());
  const total = filtered.length;
  const start = (page - 1) * pageSize;
  filtered = filtered.slice(start, start + pageSize);
  result = {
    data: filtered,
    total: total,
    page: page,
    page_size: pageSize,
    has_more: start + filtered.length < total
  };
} else {
  const total = holdings.length;
  const start = (page - 1) * pageSize;
  const data = holdings.slice(start, start + pageSize);
  result = {
    data: data,
    total: total,
    page: page,
    page_size: pageSize,
    has_more: start + data.length < total
  };
}

return [{ json: result }];

// ============================================================
// 接收爬蟲 POST 資料，更新 workflow staticData
// Body: { snapshots: [...], holdings: [...] }
// ============================================================

const body = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (body.snapshots && Array.isArray(body.snapshots)) {
  staticData.snapshots = JSON.stringify(body.snapshots);
  staticData.generated_at = body.generated_at || new Date().toISOString();
}

if (body.holdings && Array.isArray(body.holdings)) {
  staticData.holdings = JSON.stringify(body.holdings);
}

return [{
  json: {
    success: true,
    message: `Updated: ${body.snapshots?.length || 0} snapshots, ${body.holdings?.length || 0} holdings`,
    timestamp: new Date().toISOString()
  }
}];
